    /// <summary>
    /// Changes the photo of a chat. Supported only for basic groups, supergroups and channels. Requires can_change_info member right
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetChatPhotoAsync(long chatId = default, InputChatPhoto photo = default)
    {

           using var activity =  StartCallActivity("SetChatPhotoAsync", typeof(SetChatPhoto).FullName ?? "SetChatPhotoAsync");

           try
           {
             return client.SetChatPhotoAsync(chatId, photo);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
